import { describe, expect, it, afterAll } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { compileWorkflowScript, analyzeWorkflowScript, toActorGraph } from "../src/index.js";

/**
 * Gamos M1.5 compiler acceptance (directive §12 / contract 05 revision 2).
 *
 * The GamePlan artifact generated by @zcode/gamos-domain must be accepted by
 * THIS package's real compiler and analyzer: the script IS the GamePlan, and
 * the existing Dynamic Workflow definition/compiler/runtime is the only
 * execution authority (no second compiler, no second runtime — contract 05 §2).
 *
 * This test imports the generator from the workspace source (the package has
 * no runtime dependency on this package: the acceptance direction is
 * gamos-domain script → dynamic-workflow compiler).
 */

import {
  parseGamePlan,
  registerCapability,
  buildMachineDiscoveryRecord,
  detectProjectEngines,
  resolveGamingIntent,
  buildGamePlanWorkflowScript,
} from "../../../../../packages/gamos-domain/src/contract.js";
import type { GamingModelContext } from "../../../../../packages/gamos-domain/src/contract.js";

const COMPLETE_CAPABILITY_RECORD = {
  id: "core/project.inspect",
  version: "1.0.0",
  title: "Inspect game project",
  description: "Read-only structural inspection of a game project.",
  engineFamily: "core",
  input: { type: "object", properties: { projectRoot: { type: "string" } }, required: ["projectRoot"] },
  output: { type: "object", properties: { report: { type: "string" } }, required: ["report"] },
  permissions: [{ kind: "command-execution" as const, scope: "read-only", rationale: "filesystem listing only" }],
  availability: { state: "available" as const, reason: "local probes present", prerequisites: [] },
  provenance: { publisher: "official" as const, source: "gamos-2.0 repository", commitSha: "a".repeat(40) },
  provider: { kind: "agent-tool" as const, identity: "gamos-domain@1.0.0" },
  prerequisites: [],
  compatibility: { runtime: "node>=24", notes: "pure data" },
  reversibility: { kind: "reversible" as const, notes: "read-only" },
  idempotency: { repeatable: true },
  timeout: { defaultMs: 30000, maxMs: 120000 },
  cancellation: { supported: true, semantics: "cooperative" },
  verification: { method: "output-schema" as const, spec: "output schema above" },
};

const PLAN_INPUT = {
  planId: "plan-001",
  conceptRef: { conceptId: "concept-001", conceptSha256: "a".repeat(64) },
  engineBinding: { engineFamily: "unity", bindingReason: "project dependencies discovered (M1.3)" },
  steps: [
    {
      stepId: "step-1",
      capability: { capabilityId: "core/project.inspect", capabilityVersion: "1.0.0", input: {} },
      dependsOn: [],
      constraints: { read_only: true, timeout_ms: 30000 },
    },
    {
      stepId: "step-2",
      capability: { capabilityId: "core/project.inspect", capabilityVersion: "1.0.0", input: {} },
      dependsOn: ["step-1"],
      constraints: { read_only: true },
    },
  ],
  permissions: [],
  acceptanceRecord: { recordId: "acc-001", recordSha256: "b".repeat(64) },
  artifactExpectations: [],
  executionConstraints: { read_only: true, requiresApproval: true, maxConcurrency: 2 },
  createdAt: "2026-11-05T20:30:00Z",
  provenance: { authoredBy: "user-selected-model", modelId: "nvidia/nemotron-3-ultra-550b-a55b:free" },
};

const roots: string[] = [];
afterAll(() => {
  for (const dir of roots) rmSync(dir, { recursive: true, force: true });
});

function makeContext(unityInstalled: boolean): GamingModelContext {
  const root = mkdtempSync(join(tmpdir(), "gamos-m15-compile-"));
  roots.push(root);
  mkdirSync(join(root, "ProjectSettings"), { recursive: true });
  writeFileSync(join(root, "ProjectSettings", "ProjectVersion.txt"), "m_EditorVersionWithRevision: 2022.3.10f1 (abcdef123456)\n");
  const registry = new Map();
  registry.set("core/project.inspect", registerCapability(COMPLETE_CAPABILITY_RECORD));
  const resolution = resolveGamingIntent({
    message: "Generate a read-only plan for validating this game project.",
    workspaceRoot: root,
    projectDetection: detectProjectEngines(root),
    machineDiscovery: buildMachineDiscoveryRecord(
      root,
      [
        unityInstalled
          ? { engineFamily: "unity" as const, installed: true, rawVersion: "2022.3.10f1", headlessCapable: true, displayServerRequired: false }
          : { engineFamily: "unity" as const, installed: false, notes: "Unity editor not found on PATH or common install locations", headlessCapable: false, displayServerRequired: false },
      ],
      { platform: "linux", arch: "x64" },
      "2026-11-05T22:00:00Z",
    ),
    registry,
    requestedCapabilities: [{ id: "core/project.inspect" }],
    now: "2026-11-05T22:00:00Z",
  });
  if (!resolution.context) throw new Error("fixture: no context");
  return resolution.context;
}

describe("Gamos GamePlan script acceptance by the real compiler (M1.5)", () => {
  it("a generated read-only GamePlan script typechecks clean against the facade", () => {
    const context = makeContext(true);
    const artifact = buildGamePlanWorkflowScript(parseGamePlan(PLAN_INPUT), context);
    const result = compileWorkflowScript(artifact.scriptText);
    expect(result.diagnostics).toEqual([]);
    expect(result.ok).toBe(true);
  });

  it("the analyzer accepts the script and its actor graph carries the plan's step agents", () => {
    const context = makeContext(true);
    const artifact = buildGamePlanWorkflowScript(parseGamePlan(PLAN_INPUT), context);
    const analysis = analyzeWorkflowScript(artifact.scriptText);
    expect(analysis.ok).toBe(true);
    expect(analysis.graph).toBeDefined();
    const actors = toActorGraph(analysis.graph!);
    const names = actors.nodes.map((a: { name?: string }) => a.name ?? "");
    expect(names).toContain("gamos-plan-001-step-1");
    expect(names).toContain("gamos-plan-001-step-2");
    // dependency ordering is structural: step-2's ask must happen after step-1's
    const causality = analysis.causality!;
    expect(JSON.stringify(causality)).toContain("ask");
  });

  it("the fail-closed guard variant still compiles (guards are runtime semantics, not syntax errors)", () => {
    const context = makeContext(false);
    const guardPlan = parseGamePlan({
      ...PLAN_INPUT,
      steps: [
        {
          stepId: "step-1",
          capability: { capabilityId: "core/project.inspect", capabilityVersion: "1.0.0", input: {} },
          dependsOn: [],
          constraints: { read_only: true },
        },
      ],
    });
    const artifact = buildGamePlanWorkflowScript(guardPlan, context);
    expect(artifact.guards.some((g) => g.family === "unity" && g.state === "unavailable")).toBe(true);
    const result = compileWorkflowScript(artifact.scriptText);
    expect(result.ok).toBe(true);
    const analysis = analyzeWorkflowScript(artifact.scriptText);
    expect(analysis.ok).toBe(true);
  });
});
